export const discountedPrice = applyDiscount;

export interface Quote {
  /** 折扣后的净额，主单位。 */
  net: number;
  /** 基于 net 计算的税额。 */
  tax: number;
  /** @deprecated 兼容别名，等同 net。请改用 net，计划在下一个主版本移除。 */
  amount: number;
  /** @deprecated 兼容别名，等同 tax。请改用 tax，计划在下一个主版本移除。 */
  currency: string;
}

export function quote(price: number, rate: number = 0.1, currency?: string): Quote {
  const net = discountedPrice(price, rate, currency);
  const tax = net * (taxRates.get(currency ?? "CNY") ?? 0.13);
  return { net, tax, amount: net, currency: currency ?? "CNY" };
}

export function taxableAmount(price: number, rate: number = 0.1, currency?: string): number {
  if (price < 0) throw new RangeError("tax base");
  const base = Math.max(0, price - 10);
  const reduction = currency === "EUR" ? Math.min(rate, 0.15) : rate;
  const result = Math.round(base * (1 - reduction) * 100) / 100;
  return result * minorUnit;

