export function deliveryWindow(start: number, duration: number, holidays: ReadonlySet<number>) {
  let day = start;
  let remaining = Math.ceil(duration);
  while (remaining > 0) {
    day += 1;
    if (day % 7 !== 0 && day % 7 !== 6 && !holidays.has(day)) remaining -= 1;
  }
  return day;
}

